import { assert } from '../util.mjs';

export const ADMISSION_LIFETIME = Symbol('admission-lifetime');

/** A generation may retire only when its admission inventory is still current. */
export function createAdmissionLifetime(track) {
    let active = 0;
    let version = 0;
    let fenced = false;
    return Object.freeze({
        track(operation, internal) {
            // Work generated by a claimed durable job can finish during drain.
            assert(!fenced || internal, 'Runner is closed for admission.', 'RUNNER_CLOSED');
            const work = track(operation, internal);
            active++;
            version++;
            const settled = () => { active--; };
            work.then(settled, settled);
            return work;
        },
        checkpoint() { return active === 0 ? version : null; },
        fence(checkpoint) {
            if (checkpoint === null || active !== 0 || version !== checkpoint) return false;
            fenced = true;
            return true;
        },
    });
}
